import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import BarraNavegacion from "./componentes/diseno/BarraNavegacion";
import DatosDelSostenedor from "./paginas/Sostenedor/DatosDelSostenedor";
import EstructuraDeCurso from "./paginas/Establecimientos/EstructuraDeCurso";
import AlumnosDelCurso from "./paginas/alumnos/AlumnosDelCurso";
import Login from "./paginas/auth/login";                 // 👈 en minúsculas según tu carpeta
import { AuthProvider, useAuth }  from "./contexto/AuthContext"; // 👈 carpeta 'contexto' en español

function ProtectedRoute({ children }) {
  const { isAuth, status } = useAuth();
  if (status !== "ready") return null; // opcional: spinner de carga
  if (!isAuth) return <Navigate to="/login" replace />;
  return children;
}

function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <BarraNavegacion />
        <main>
          <Routes>
            {/* Login público */}
            <Route path="/login" element={<Login />} />

            {/* Rutas protegidas (requieren sesión) */}
            <Route
              path="/"
              element={
                <ProtectedRoute>
                  <DatosDelSostenedor />
                </ProtectedRoute>
              }
            />
            <Route
              path="/sostenedor"
              element={
                <ProtectedRoute>
                  <DatosDelSostenedor />
                </ProtectedRoute>
              }
            />
            <Route
              path="/establecimientos/:id/estructura"
              element={
                <ProtectedRoute>
                  <EstructuraDeCurso />
                </ProtectedRoute>
              }
            />
            <Route
              path="/establecimientos/:id/cursos/:cursoId/alumnos"
              element={
                <ProtectedRoute>
                  <AlumnosDelCurso />
                </ProtectedRoute>
              }
            />

            {/* Redirección por defecto */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </BrowserRouter>
    </AuthProvider>
  );
}

export default App;
